// Does the escape byte matter OUTSIDE an enclosure, and does a doubled enclosure still work?
$cases = [
    "a\\,b,c\n",
    "a\\\nb\n",
    "\"a\"\"b\"\n",
    "\"a\\\"\"b\"\n",
    "\"a\",\\\"b\n",
    "x\\\n",
];
foreach ($cases as $i => $text) {
    $h = fopen("php://memory", "w+");
    fwrite($h, $text);
    rewind($h);
    echo "case $i\n";
    while (($row = fgetcsv($h, 0, ",", "\"", "\\")) !== false) {
        var_dump($row);
    }
    fclose($h);
}
